      out.write("<script>\n");
      out.write("(function () {\n");
      out.write("    \"use strict\";\n");
      out.write("\n");
      out.write("    /* ── 1. Password show/hide toggle ── */\n");
      out.write("    var pwField  = document.getElementById(\"password\");\n");
      out.write("    var pwToggle = document.getElementById(\"pwToggle\");\n");
      out.write("    var eyeOpen  = document.getElementById(\"eyeOpen\");\n");
      out.write("    var eyeClosed = document.getElementById(\"eyeClosed\");\n");
      out.write("\n");
      out.write("    pwToggle.addEventListener(\"click\", function () {\n");
      out.write("        var isPassword = pwField.type === \"password\";\n");
      out.write("        pwField.type   = isPassword ? \"text\" : \"password\";\n");
      out.write("        eyeOpen.style.display  = isPassword ? \"none\"  : \"block\";\n");
      out.write("        eyeClosed.style.display = isPassword ? \"block\" : \"none\";\n");
      out.write("        pwField.focus();\n");
      out.write("    });\n");
      out.write("\n");
      out.write("    /* ── 2. Clear success message after 3 s ── */\n");
      out.write("    var successAlert = document.getElementById(\"successAlert\");\n");
      out.write("    if (successAlert) {\n");
      out.write("        setTimeout(function () {\n");
      out.write("            successAlert.style.transition = \"opacity 0.5s ease\";\n");
      out.write("            successAlert.style.opacity    = \"0\";\n");
      out.write("            setTimeout(function () {\n");
      out.write("                successAlert.style.display = \"none\";\n");
      out.write("            }, 500);\n");
      out.write("        }, 3000);\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    /* ── 3. Client-side form validation ── */\n");
      out.write("    var form         = document.getElementById(\"loginForm\");\n");
      out.write("    var emailField   = document.getElementById(\"email\");\n");
      out.write("    var roleField    = document.getElementById(\"role\");\n");
      out.write("    var captchaField = document.getElementById(\"captchaInput\");\n");
      out.write("\n");
      out.write("    /* helper – show/hide field error */\n");
      out.write("    function setError(field, errorId, show) {\n");
      out.write("        var errEl = document.getElementById(errorId);\n");
      out.write("        if (show) {\n");
      out.write("            field.classList.add(\"is-invalid\");\n");
      out.write("            errEl.style.display = \"block\";\n");
      out.write("        } else {\n");
      out.write("            field.classList.remove(\"is-invalid\");\n");
      out.write("            errEl.style.display = \"none\";\n");
      out.write("        }\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    /* live validation – clear error on typing */\n");
      out.write("    [emailField, pwField, captchaField].forEach(function (f) {\n");
      out.write("        f.addEventListener(\"input\", function () {\n");
      out.write("            f.classList.remove(\"is-invalid\");\n");
      out.write("            var id = f.id + \"Error\";\n");
      out.write("            var el = document.getElementById(id);\n");
      out.write("            if (el) el.style.display = \"none\";\n");
      out.write("        });\n");
      out.write("    });\n");
      out.write("    roleField.addEventListener(\"change\", function () {\n");
      out.write("        roleField.classList.remove(\"is-invalid\");\n");
      out.write("        document.getElementById(\"roleError\").style.display = \"none\";\n");
      out.write("    });\n");
      out.write("\n");
      out.write("    /* email regex */\n");
      out.write("    var emailRe = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\n");
      out.write("\n");
      out.write("    form.addEventListener(\"submit\", function (e) {\n");
      out.write("        var valid = true;\n");
      out.write("\n");
      out.write("        /* email */\n");
      out.write("        if (!emailField.value.trim() || !emailRe.test(emailField.value.trim())) {\n");
      out.write("            setError(emailField, \"emailError\", true);\n");
